def image(path):
    return '../'+path

def external(url):
    return ' target="_blank" rel="noopener noreferrer"' if url.startswith('https:') else ''

def shell(title,body):
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{e(title)} — Queena Zheng</title><meta name="description" content="{e(title)}. Product design and interaction work by Queena Zheng."><link rel="stylesheet" href="../styles.css"><link rel="stylesheet" href="../projects.css"></head>
<body class="project-page"><a class="skip-link" href="#main">Skip to content</a><header class="topbar"><div class="container topbar-inner"><a class="brand" href="../index.html">Queena Zheng</a><nav class="nav" aria-label="Project navigation"><a class="nav-link" href="../index.html#works">Selected work</a><a class="nav-link" href="archive.html">Archive</a><a class="nav-link" href="../index.html#contact">Contact</a></nav></div></header><main id="main" class="container">{body}</main><footer class="footer"><div class="container footer-inner"><p>© 2026 Queena Zheng</p><a class="inline-link" href="../index.html#works">Back to selected work ↑</a></div></footer></body></html>'''

def case(p,next_p):
    action=f'<a class="pill" href="{e(p["url"])}"{external(p["url"])}>{e(p["action"])}</a>'
    if p.get('secondary'):
        url,label=p['secondary'];action+=f'<a class="pill pill-secondary" href="{e(url)}"{external(url)}>{e(label)}</a>'
    parts=[f'''<header class="case-header"><a class="inline-link" href="../index.html#works">← Selected work</a><p class="case-kicker">{e(p['category'])}</p><h1 class="case-title">{e(p['name'])}</h1><p class="case-deck">{e(p['headline'])}</p><p class="body-copy">{e(p['summary'])}</p><dl class="case-meta"><div><dt>Design focus</dt><dd>{e(p['focus'])}</dd></div><div><dt>Project format</dt><dd>{e(p['status'])}</dd></div><div><dt>Practice</dt><dd>Product design × Creative technology</dd></div></dl><div class="case-actions">{action}</div><p class="case-note">{e(p['note'])}</p></header><figure class="case-figure"><img src="{image(p['image'])}" alt="{e(p['name'])} project visual"><figcaption>{e(p['caption'])}</figcaption></figure>''']
    if p.get('flow'):
        parts.append('<section class="case-section"><h2>Experience at a glance</h2><div class="case-prose"><div class="case-flow">'+''.join(f'<span>{i+1:02d} · {e(x)}</span>' for i,x in enumerate(p['flow']))+'</div></div></section>')
    for title,content in p['sections']:
        parts.append(f'<section class="case-section"><h2>{e(title)}</h2><div class="case-prose">{content}</div></section>')
    for index,(src,caption) in enumerate(p.get('gallery',[])):
        parts.append(f'<figure id="{"documentation" if index == 0 else "detail-"+str(index)}" class="case-figure"><a href="{image(src)}"><img loading="lazy" src="{image(src)}" alt="{e(caption)}"></a><figcaption>{e(caption)} Open image for a closer view.</figcaption></figure>')
    parts.append(f'<nav class="case-next" aria-label="More work"><a class="inline-link" href="archive.html">Browse all project explorations →</a><a class="inline-link" href="{next_p["slug"]}.html">Next: {e(next_p["name"])} →</a></nav>')
    return shell(p['name'],''.join(parts))

if __name__ == '__main__':
    all_projects=PROJECTS+ART
    for p in all_projects:
        if p['url'] == '#documentation':
            overview='assets/art/'+p['slug']+'-overview.jpg'
            p['gallery']=[(overview, 'Original portfolio development and project framing.')]+p.get('gallery',[])
    for i,p in enumerate(all_projects):
        (ROOT/(p['slug']+'.html')).write_text(case(p,all_projects[(i+1)%len(all_projects)]))
    body='<header class="case-header"><p class="case-kicker">The wider practice</p><h1 class="case-title">Experiments & earlier work</h1><p class="case-deck">Physical objects, speculative services, and interfaces built to ask a question.</p><p class="body-copy">A supporting collection alongside the four selected projects. Each entry names the artifact you can actually explore.</p></header><div class="archive-grid">'
    entries=[dict(name=p['name'],image=p['image'],summary=p['summary'],url=p['slug']+'.html',label='Read project →',note=p['status']) for p in ART]+MORE
    for p in entries:
        body+=f'<article class="work-card glass-card"><a href="{e(p["url"])}"{external(p["url"])}><img loading="lazy" src="{image(p["image"])}" alt="{e(p["name"])} project visual"></a><div class="card-content"><h2 class="card-title">{e(p["name"])}</h2><p class="card-text">{e(p["summary"])}</p><a class="inline-link" href="{e(p["url"])}"{external(p["url"])}>{e(p["label"])}</a><p class="project-status">{e(p["note"])}</p></div></article>'
    (ROOT/'archive.html').write_text(shell('Experiments & earlier work',body+'</div>'))
    print(f'Built {len(all_projects)} project pages and archive.')
